import JSON
import Distributions: mgf, HalfNormal

"""
	gen( t, sigma, name )

Generate half-normal MGF fixture data and write to file.

# Arguments

* `t`: input values
* `sigma`: scale parameters
* `name::AbstractString`: output filename

# Examples

``` julia
julia> sigma = rand( 1000 );
julia> gen( sigma, \"data.json\" );
```
"""
# Get the filename:
file = @__FILE__

# Extract the directory in which this file resides:
dir = dirname(file)

function gen( t, sigma, name )
	z = Array{Float64}( undef, length(t) )

	for i in eachindex(t)
	z[i] = mgf( HalfNormal( sigma[i] ) , t[i] )
	end

	data = Dict([
		("t", t),
		("sigma", sigma),
		("expected", z)
	])

	filepath = joinpath( dir, name )
	open( filepath, "w" ) do io
		write( io, JSON.json( data ) )
		write( io, "\n" )
	end
end

# Generate fixtures...
t = rand( 1000 ) .* 5.0
sigma = rand( 1000 ) .* 5.0 .+ 0.1
gen( t, sigma, "data.json" )
